function swap(
  uint256 amountIn,
  uint256 minAmountOut,
  address tokenIn,
  address to,
  uint256 deadline
) external returns (uint256 amountOut) {
  require(block.timestamp <= deadline, "expired");
  (uint256 reserveIn, uint256 reserveOut) = _getReserves(tokenIn);
  uint256 amountInWithFee = amountIn * 997 / 1000;
  amountOut = (amountInWithFee * reserveOut) / (reserveIn + amountInWithFee);
  require(amountOut >= minAmountOut, "slippage: insufficient output");
  _transferIn(tokenIn, amountIn);
  _transferOut(tokenIn, to, amountOut);
  _updateReserves();
}

function healthFactor(address borrower) public view returns (uint256) {
  uint256 collateralValue = _collateralValueUSD(borrower);
  uint256 debtValue = _debtValueUSD(borrower);
  if (debtValue == 0) return type(uint256).max;
  return (collateralValue * LIQUIDATION_THRESHOLD) / debtValue; // scaled 1e18
}

function liquidate(address borrower, uint256 repayAmount) external {
  require(healthFactor(borrower) < 1e18, "position healthy");
  uint256 maxRepay = _debtOf(borrower) / 2; // partial liquidation cap
  uint256 actualRepay = repayAmount > maxRepay ? maxRepay : repayAmount;
  uint256 collateralSeized = (actualRepay * (1e18 + LIQUIDATION_BONUS)) / _price();
  _repayDebt(borrower, actualRepay);
  _seizeCollateral(borrower, msg.sender, collateralSeized);
}

struct Proposal { bytes32 id; uint256 eta; bool executed; address target; bytes data; }
mapping(bytes32 => Proposal) public proposals;
uint256 public constant DELAY = 2 days;
uint256 public constant GRACE_PERIOD = 14 days;

function queue(address target, bytes calldata data) external onlyAfterPassedVote returns (bytes32 id) {
  id = keccak256(abi.encode(target, data, block.timestamp));
  proposals[id] = Proposal(id, block.timestamp + DELAY, false, target, data);
}

function execute(bytes32 id) external {
  Proposal storage p = proposals[id];
  require(p.eta != 0, "unknown proposal");
  require(block.timestamp >= p.eta, "too early");
  require(block.timestamp <= p.eta + GRACE_PERIOD, "stale, expired");
  require(!p.executed, "already executed");
  p.executed = true;
  (bool ok, ) = p.target.call(p.data);
  require(ok, "execution failed");
}

function testFuzz_SwapNeverDecreasesK(uint256 amountIn) public {
  amountIn = bound(amountIn, 1, 1_000_000e18);
  (uint256 reserveInBefore, uint256 reserveOutBefore) = pool.getReserves();
  uint256 kBefore = reserveInBefore * reserveOutBefore;

  tokenA.mint(address(this), amountIn);
  tokenA.approve(address(pool), amountIn);
  pool.swap(amountIn, 0, address(tokenA), address(this), block.timestamp + 1);

  (uint256 reserveInAfter, uint256 reserveOutAfter) = pool.getReserves();
  uint256 kAfter = reserveInAfter * reserveOutAfter;

  assertGe(kAfter, kBefore, "k decreased after swap");
}

