let lastProcessedBlock = await db.getCheckpoint();
const CONFIRMATIONS = 5;

async function pollLoop() {
  const latest = await provider.getBlockNumber();
  const safeHead = latest - CONFIRMATIONS;
  if (safeHead <= lastProcessedBlock) return;

  const events = await contract.queryFilter(
    contract.filters.Deposit(),
    lastProcessedBlock + 1,
    safeHead
  );
  for (const e of events) {
    await processEventIdempotently(e); // keyed by (txHash, logIndex)
  }
  lastProcessedBlock = safeHead;
  await db.saveCheckpoint(lastProcessedBlock);
}
setInterval(pollLoop, 15_000);

