export function handleSale(event: SaleEvent): void {
  let sale = new Sale(
    event.transaction.hash.concatI32(event.logIndex.toI32())
  );
  sale.tokenId = event.params.tokenId;
  sale.seller = event.params.seller;
  sale.buyer = event.params.buyer;
  sale.priceWei = event.params.price;
  sale.timestamp = event.block.timestamp;
  sale.save();
}

function checkUpkeep(bytes calldata) external view returns (bool upkeepNeeded, bytes memory) {
  (, int256 price,, uint256 updatedAt,) = priceFeed.latestRoundData();
  require(block.timestamp - updatedAt < STALENESS_THRESHOLD, "stale price");
  require(price > 0, "invalid price");
  uint256 currentPrice = uint256(price);
  upkeepNeeded = currentPrice <= lastRebalancePrice * 90 / 100;
}

function performUpkeep(bytes calldata) external {
  (, int256 price,, uint256 updatedAt,) = priceFeed.latestRoundData();
  require(block.timestamp - updatedAt < STALENESS_THRESHOLD, "stale price");
  require(uint256(price) <= lastRebalancePrice * 90 / 100, "condition no longer met");
  _rebalance(uint256(price));
  lastRebalancePrice = uint256(price);
}

async function verifySiweLogin(message, signature, expectedNonce) {
  const siweMessage = new SiweMessage(message);
  const fields = await siweMessage.verify({ signature });

  if (siweMessage.nonce !== expectedNonce) throw new Error("nonce mismatch/replay");
  if (siweMessage.domain !== EXPECTED_DOMAIN) throw new Error("domain mismatch");
  const now = new Date();
  if (siweMessage.expirationTime && now > new Date(siweMessage.expirationTime))
    throw new Error("expired");

  await db.consumeNonce(expectedNonce); // one-time use
  return fields.data.address;
}

let nonceCounter = await provider.getTransactionCount(wallet.address, "pending");
const mutex = new Mutex();

async function sendTx(txRequest) {
  return mutex.runExclusive(async () => {
    const nonce = nonceCounter++;
    const feeData = await provider.getFeeData();
    const tx = await wallet.sendTransaction({
      ...txRequest,
      nonce,
      maxFeePerGas: feeData.maxFeePerGas * 120n / 100n,
      maxPriorityFeePerGas: feeData.maxPriorityFeePerGas * 120n / 100n,
    });
    pendingTxs.set(nonce, { tx, sentAt: Date.now() });
    return tx;
  });
}

